package main

import "fmt"

func main() {
    inventory := map[string]int{
        "apples":  5,
        "oranges": 3,
    }
    if _, exists := inventory["bananas"]; exists {
        fmt.Println("exists")
    } else {
        fmt.Println("not found")
    }
}

